#include "sda_falcon_bkz.h"
int main(void){char version[128]={0};int available=sda_falcon_bkz_available(version,sizeof version);if(available&&!version[0])return 1;mpz_t D,A[19],row[20];mpz_init_set_ui(D,10);for(int i=0;i<19;i++){mpz_init_set_si(A[i],-i-1);mpz_init(row[i]);mpz_set_si(row[i],(i+1)*10+7*(-i-1));}mpz_init_set_ui(row[19],7);sda_falcon_bkz_result r={0};if(sda_falcon_recover((const mpz_t*)row,D,(const mpz_t*)A,&r)||r.q!=7)return 2;for(int i=0;i<19;i++)if(r.p[i]!=(sda_u128)(i+1))return 3;for(int i=0;i<20;i++)mpz_neg(row[i],row[i]);if(sda_falcon_recover((const mpz_t*)row,D,(const mpz_t*)A,&r)||r.q!=7)return 4;for(int i=0;i<20;i++)mpz_clear(row[i]);for(int i=0;i<19;i++)mpz_clear(A[i]);mpz_clear(D);return 0;}
